-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (6929, 12, 'Erhalt und Sanierung von Autobahnen, Straßen und Brücken ausreichend und verlässlich finanzieren', 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'gemischt', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'bund', null, true, null),
  (6930, 12, 'Vorrang für Sanierung vor Neu- und Ausbau von Straßen', 'Bündelt knappe Planungs- und Baukapazitäten auf den Erhalt, wie es der Bundesrechnungshof für die Brücken fordert; weniger Neubau kann Engpässe auf überlasteten Strecken länger bestehen lassen.', 'gemischt', 'https://www.bundesrechnungshof.de/SharedDocs/Statements/DE/2025/brueckenmodernisierung.html', 'bund', null, true, null),
  (6931, 12, 'Großes Investitionsprogramm, Investitionen von der Schuldenbremse ausnehmen', 'Mehr Geld für Bund, Länder und Kommunen kann Sanierungsstau abbauen; ob es bei Straßen und Brücken ankommt und verbaut werden kann, hängt von Personal und Verfahren ab. Braucht eine Grundgesetzänderung, wie sie 2025 für das Sondervermögen beschlossen wurde.', 'gemischt', null, 'bund', null, true, null),
  (6932, 12, 'Finanzierungskreislauf Straße: Lkw-Maut für die Autobahn GmbH, privates Kapital', 'Macht die Finanzierung der Autobahnen planbarer und unabhängiger vom Haushalt; öffentlich-private Partnerschaften waren laut Bundesrechnungshof bisher oft teurer als konventionelle Vergabe.', 'gemischt', null, 'bund', null, true, null),
  (6933, 12, 'Planung und Genehmigung beschleunigen, Ersatzneubauten ohne Planfeststellung oder Umweltprüfung', 'Verkürzt die Zeit bis zum Ersatz maroder Brücken, bei denen sich an Lage und Umweltwirkung wenig ändert; seit 2023 gibt es dafür schon Erleichterungen. Nach Bundesrechnungshof und KfW bremsen vor allem Personal und Geld, nicht nur die Verfahren.', 'gemischt', null, 'bund', null, true, null),
  (6934, 12, 'Kommunalfinanzen stärken: Altschuldenlösung, Gemeindefinanzreform', 'Gibt überschuldeten Kommunen wieder Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden die Kommunen. Eine Altschuldenlösung braucht eine Einigung von Bund und Ländern.', 'gemischt', null, 'bund', null, true, null),
  (6935, 12, 'Güterverkehr von der Straße auf die Schiene verlagern', 'Schwere Lkw belasten Brücken am stärksten, weniger Lkw verlangsamen den Verschleiß; eine spürbare Verlagerung braucht aber Jahre und mehr Kapazität auf der Schiene.', 'gemischt', null, 'bund', null, true, null),
  (6936, 12, 'Radwegenetz ausbauen und dauerhaft finanzieren', 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'gemischt', null, 'bund', null, true, null),
  (6937, 12, 'Tempo 30 innerorts erleichtern oder zur Regel machen', 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern deutlich; auf Landstraßen und an Hauptverkehrsachsen, wo viele schwere Radunfälle passieren, ändert es nichts.', 'belegt', null, 'bund', null, true, null),
  (7060, 12, 'Landes- und kommunale Straßen und Brücken sanieren (Landesprogramm)', 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'gemischt', null, 'land', null, true, null),
  (7061, 12, 'Kommunen finanziell stärken: Finanzausgleich, Investitionspauschalen, Altschulden (Landesprogramm)', 'Gibt Kommunen Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden sie selbst, und der Landeshaushalt ist begrenzt.', 'gemischt', null, 'land', null, true, null),
  (7062, 12, 'Planung, Genehmigung und Vergabe im Land beschleunigen (Landesprogramm)', 'Das Land kann Bauordnung, Vergaberecht und Verwaltungsabläufe selbst ändern und so Verfahren verkürzen; laut KfW bremst aber vor allem fehlendes Personal.', 'gemischt', null, 'land', null, true, null),
  (7063, 12, 'Bauverwaltungen personell und finanziell stärken (Landesprogramm)', 'Setzt am größten Hemmnis an, das die KfW nennt; Ingenieurinnen und Ingenieure sind knapp, neue Stellen lassen sich nicht sofort besetzen.', 'gemischt', null, 'land', null, true, null),
  (7064, 12, 'Radwege ausbauen und sanieren, sichere und durchgängige Netze (Landesprogramm)', 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'gemischt', null, 'land', null, true, null),
  (7065, 12, 'Tempo 30 innerorts ausweiten, besonders an Schulen, Kitas und Seniorenheimen (Landesprogramm)', 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern; seit 2024 können Länder und Kommunen Tempo 30 leichter anordnen.', 'belegt', null, 'land', null, true, null),
  (7066, 12, 'Verkehrserziehung und Sicherheitsangebote, auch für Ältere (Landesprogramm)', 'Richtet sich an Gruppen mit hohem Risiko, etwa ältere Menschen auf Pedelecs; wie stark Trainings die Zahl schwerer Unfälle senken, ist kaum untersucht.', 'offen', null, 'land', null, true, null),
  (8682, 12, 'Unfallschwerpunkte beseitigen und gefährliche Kreuzungen sicher umgestalten (Land)', 'Setzt dort an, wo sich Unfälle mit Radfahrenden häufen, etwa an Kreuzungen mit abbiegenden Autos; Auswertungen zeigen oft Rückgänge, strengere Studien mit Kontrolle der Regression zur Mitte finden aber deutlich kleinere Effekte.', 'gemischt', 'https://trid.trb.org/View/482195', 'land', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 12 and id not in (6929, 6930, 6931, 6932, 6933, 6934, 6935, 6936, 6937, 7060, 7061, 7062, 7063, 7064, 7065, 7066, 8682);

