  (6938, 12, 11, null, 'Auskömmliche Finanzierung von Autobahnen, Brücken und Straßen', '{1201}', 6929, 2, 3, null, 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6939, 12, 11, null, 'Ersatzneubauten per Anzeigeverfahren statt Planfeststellung zulassen', '{1201,1203}', 6933, 2, 3, null, 'Verkürzt die Zeit bis zum Ersatz maroder Brücken, bei denen sich an Lage und Umweltwirkung wenig ändert; seit 2023 gibt es dafür schon Erleichterungen. Nach Bundesrechnungshof und KfW bremsen vor allem Personal und Geld, nicht nur die Verfahren.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'gemischt', '2026-09-30', false, true, null),
  (6940, 12, 11, null, 'Neue Radwege und Ausbau des Radnetzes', '{1204}', 6936, 2, 2, null, 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=75', null, 'gemischt', '2026-09-30', false, true, null),
  (6941, 12, 12, null, 'Autobahnnetz und vor allem Brücken dringend sanieren', '{1201}', 6929, 2, 3, null, 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6942, 12, 12, null, 'Deutschlandpakt zur Planungs- und Genehmigungsbeschleunigung fortsetzen', '{1201,1203}', 6933, 2, 3, null, 'Verkürzt die Zeit bis zum Ersatz maroder Brücken, bei denen sich an Lage und Umweltwirkung wenig ändert; seit 2023 gibt es dafür schon Erleichterungen. Nach Bundesrechnungshof und KfW bremsen vor allem Personal und Geld, nicht nur die Verfahren.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=9', null, 'gemischt', '2026-09-30', false, true, null),
  (6943, 12, 12, null, 'Lösung für kommunale Altschulden, Kommunalfinanzen verbessern', '{1202}', 6934, 1, 2, null, 'Gibt überschuldeten Kommunen wieder Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden die Kommunen. Eine Altschuldenlösung braucht eine Einigung von Bund und Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=18', null, 'gemischt', '2026-09-30', false, true, null),
  (6944, 12, 12, null, 'Größere Planungskapazitäten der Kommunen, gemeinsamer Personaleinsatz', '{1203}', null, 1, 2, null, 'Setzt am Personalmangel der Bauverwaltungen an, den die KfW als größtes Hemmnis nennt; wie der Bund dazu beitragen will, bleibt offen, zuständig sind Länder und Kommunen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=18', null, 'offen', '2026-09-30', false, true, null),
  (6945, 12, 12, null, 'Verkehr von der Straße auf Schiene und Wasserstraße lenken', '{1201}', 6935, 1, 2, null, 'Schwere Lkw belasten Brücken am stärksten, weniger Lkw verlangsamen den Verschleiß; eine spürbare Verlagerung braucht aber Jahre und mehr Kapazität auf der Schiene.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null),
  (6946, 12, 12, null, 'Bundesweit vernetzte Radschnellwege und Fahrradparkhäuser fördern', '{1204}', 6936, 2, 2, null, 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', null, 'gemischt', '2026-09-30', false, true, null),
  (6947, 12, 12, null, 'Vision Zero im Straßenverkehrsrecht verankern', '{1204}', null, 1, 3, null, 'Ein gesetzliches Ziel ohne Verkehrstote kann Behörden verpflichten, Sicherheit bei Planung und Anordnungen stärker zu gewichten; welche Regeln sich konkret ändern, bleibt offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', null, 'offen', '2026-09-30', false, true, null),
  (6948, 12, 13, null, 'Überjährige Finanzierung für den Erhalt von Straßen und Brücken über den Deutschlandfonds', '{1201}', 6929, 2, 3, null, 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6949, 12, 13, null, 'Sanierung statt Neubau im Straßennetz', '{1201}', 6930, 2, 3, null, 'Bündelt knappe Planungs- und Baukapazitäten auf den Erhalt, wie es der Bundesrechnungshof für die Brücken fordert; weniger Neubau kann Engpässe auf überlasteten Strecken länger bestehen lassen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', 'https://www.bundesrechnungshof.de/SharedDocs/Statements/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6950, 12, 13, null, 'Ausbau eines guten Radwegenetzes dauerhaft finanzieren', '{1204}', 6936, 2, 2, null, 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', null, 'gemischt', '2026-09-30', false, true, null),
  (6951, 12, 13, null, 'Kommunen flächendeckend Tempo 30 innerorts ermöglichen', '{1204}', 6937, 2, 3, null, 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern deutlich; auf Landstraßen und an Hauptverkehrsachsen, wo viele schwere Radunfälle passieren, ändert es nichts.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=48', null, 'belegt', '2026-09-30', false, true, null),
  (6952, 12, 13, null, 'Altschuldenfonds von Bund und Ländern', '{1202}', 6934, 1, 2, null, 'Gibt überschuldeten Kommunen wieder Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden die Kommunen. Eine Altschuldenlösung braucht eine Einigung von Bund und Ländern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=108', null, 'gemischt', '2026-09-30', false, true, null),
  (6953, 12, 14, null, 'Ersatzneubauten genehmigungsfrei stellen, Planungszeiten halbieren', '{1201,1203}', 6933, 2, 3, null, 'Verkürzt die Zeit bis zum Ersatz maroder Brücken, bei denen sich an Lage und Umweltwirkung wenig ändert; seit 2023 gibt es dafür schon Erleichterungen. Nach Bundesrechnungshof und KfW bremsen vor allem Personal und Geld, nicht nur die Verfahren.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (6954, 12, 14, null, 'Baustellen-Turbo: Ausschreibungen belohnen schnelles, fristgerechtes Bauen', '{1203}', null, 1, 3, null, 'Bonus-Malus-Regeln in Bauverträgen können Bauzeiten verkürzen und sind erprobt; an fehlendem Personal und Geld ändern sie nichts.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (6955, 12, 14, null, 'Finanzierungskreislauf Straße mit Lkw-Maut und privatem Kapital', '{1201}', 6932, 2, 2, null, 'Macht die Finanzierung der Autobahnen planbarer und unabhängiger vom Haushalt; öffentlich-private Partnerschaften waren laut Bundesrechnungshof bisher oft teurer als konventionelle Vergabe.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (6956, 12, 15, null, 'Planvolle, kontinuierliche Sanierung von Straßen und Brücken', '{1201}', 6929, 2, 3, null, 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6957, 12, 15, null, 'Keine Umweltverträglichkeitsprüfung bei Ersatzbauten, effizientere Baustellen', '{1201,1203}', 6933, 2, 3, null, 'Verkürzt die Zeit bis zum Ersatz maroder Brücken, bei denen sich an Lage und Umweltwirkung wenig ändert; seit 2023 gibt es dafür schon Erleichterungen. Nach Bundesrechnungshof und KfW bremsen vor allem Personal und Geld, nicht nur die Verfahren.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=45', null, 'gemischt', '2026-09-30', false, true, null),
  (6958, 12, 16, null, 'Gemeindefinanzreform und Altschuldenfonds für überschuldete Kommunen', '{1202}', 6934, 1, 2, null, 'Gibt überschuldeten Kommunen wieder Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden die Kommunen. Eine Altschuldenlösung braucht eine Einigung von Bund und Ländern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=13', null, 'gemischt', '2026-09-30', false, true, null),
  (6959, 12, 16, null, 'Innerorts Tempo 30 außer auf Hauptverkehrsachsen', '{1204}', 6937, 2, 3, null, 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern deutlich; auf Landstraßen und an Hauptverkehrsachsen, wo viele schwere Radunfälle passieren, ändert es nichts.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'belegt', '2026-09-30', false, true, null),
  (6960, 12, 16, null, 'Beim Straßenbau auf die Sanierung des Bestands konzentrieren, keine neuen Autobahnen', '{1201}', 6930, 2, 3, null, 'Bündelt knappe Planungs- und Baukapazitäten auf den Erhalt, wie es der Bundesrechnungshof für die Brücken fordert; weniger Neubau kann Engpässe auf überlasteten Strecken länger bestehen lassen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', 'https://www.bundesrechnungshof.de/SharedDocs/Statements/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6961, 12, 16, null, 'Güterverkehr von der Straße auf die Schiene verlagern', '{1201}', 6935, 1, 2, null, 'Schwere Lkw belasten Brücken am stärksten, weniger Lkw verlangsamen den Verschleiß; eine spürbare Verlagerung braucht aber Jahre und mehr Kapazität auf der Schiene.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'gemischt', '2026-09-30', false, true, null),
  (6962, 12, 16, null, 'Flächendeckendes bundesweites Radverkehrsnetz, sichere Radwege', '{1204}', 6936, 2, 2, null, 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=44', null, 'gemischt', '2026-09-30', false, true, null),
