  (6964, 12, 17, null, 'Gerechte Altschuldenlösung, Kommunen mit nötigen Mitteln ausstatten', '{1202}', 6934, 1, 2, null, 'Gibt überschuldeten Kommunen wieder Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden die Kommunen. Eine Altschuldenlösung braucht eine Einigung von Bund und Ländern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=16', null, 'gemischt', '2026-09-30', false, true, null),
  (6965, 12, 17, null, 'Mehr Geld für Straßenbau und die Erneuerung von Brücken', '{1201}', 6929, 2, 3, null, 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (7067, 12, 11, 'ST', 'Landesweiter Brückensanierungsplan', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=62', null, 'gemischt', '2026-09-30', false, true, null),
  (7068, 12, 11, 'ST', 'Planung und Genehmigung beschleunigen, Bearbeitungsfristen, vereinfachte Verfahren für Ersatzneubauten', '{1203}', 7062, 2, 3, null, 'Das Land kann Bauordnung, Vergaberecht und Verwaltungsabläufe selbst ändern und so Verfahren verkürzen; laut KfW bremst aber vor allem fehlendes Personal.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=55', null, 'gemischt', '2026-09-30', false, true, null),
  (7069, 12, 11, 'ST', 'Mehr Radwege bauen, regionale Radwegekonzepte unterstützen', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=63', null, 'gemischt', '2026-09-30', false, true, null),
  (7070, 12, 11, 'ST', 'Radfahrausbildung und Verkehrssicherheitsangebote, auch für Ältere', '{1204}', 7066, 1, 3, null, 'Richtet sich an Gruppen mit hohem Risiko, etwa ältere Menschen auf Pedelecs; wie stark Trainings die Zahl schwerer Unfälle senken, ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=63', null, 'offen', '2026-09-30', false, true, null),
