  (7108, 12, 17, 'MV', 'Rad- und Gehwege mitplanen, wo sinnvoll und sicher', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=90', null, 'gemischt', '2026-09-30', false, true, null),
  (7109, 12, 11, 'BE', 'Sonderprogramm für Brücken nach dem Masterplan Brücken, über 200 Mio. Euro 2026/27', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=69', null, 'gemischt', '2026-09-30', false, true, null),
  (7110, 12, 11, 'BE', 'Radwegenetz verbessern, Sanierung bestehender Radwege hat Vorrang', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=71', null, 'gemischt', '2026-09-30', false, true, null),
  (7111, 12, 12, 'BE', 'Erhalt von Straßen und Brücken statt Weiterbau der A100', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=26', null, 'gemischt', '2026-09-30', false, true, null),
  (7112, 12, 12, 'BE', 'Radverkehrsplan konsequent umsetzen, Radvorrangnetz priorisieren', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=25', null, 'gemischt', '2026-09-30', false, true, null),
  (7113, 12, 12, 'BE', 'Tempo 30 rund um Kitas, Schulen, Spielplätze und Seniorenheime', '{1204}', 7065, 2, 3, null, 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern; seit 2024 können Länder und Kommunen Tempo 30 leichter anordnen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=26', null, 'belegt', '2026-09-30', false, true, null),
  (7114, 12, 13, 'BE', 'Radverkehrsnetz mit sicheren, durchgängigen Radwegen an Hauptstraßen', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=87', null, 'gemischt', '2026-09-30', false, true, null),
  (7115, 12, 13, 'BE', 'Mehr Tempo 30 über den Lärmaktionsplan', '{1204}', 7065, 2, 3, null, 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern; seit 2024 können Länder und Kommunen Tempo 30 leichter anordnen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=85', null, 'belegt', '2026-09-30', false, true, null),
  (7116, 12, 14, 'BE', 'Radwegenetz grundlegend ausbauen, bestehende Radwege instand setzen', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=65', null, 'gemischt', '2026-09-30', false, true, null),
  (7117, 12, 15, 'BE', 'Vorausschauende Sanierung maroder Brücken, Infrastruktur-Monitoring', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (7118, 12, 15, 'BE', 'Bedarfsgerechter Ausbau der Radverkehrsinfrastruktur mit besserem Monitoring', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=43', null, 'gemischt', '2026-09-30', false, true, null),
  (7119, 12, 16, 'BE', 'Koordinierte Instandhaltung der Straßen, Masterplan Brücken umsetzen', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=69', null, 'gemischt', '2026-09-30', false, true, null),
  (7120, 12, 16, 'BE', 'Planungskapazitäten für Brücken, Rad- und Fußwege ausbauen, mehr Personal im Tiefbau', '{1203}', 7063, 2, 2, null, 'Setzt am größten Hemmnis an, das die KfW nennt; Ingenieurinnen und Ingenieure sind knapp, neue Stellen lassen sich nicht sofort besetzen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=56', null, 'gemischt', '2026-09-30', false, true, null),
  (7121, 12, 16, 'BE', 'Ausbau sicherer Radwege fortführen, lückenloses Netz nach Radnetzplan', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=65', null, 'gemischt', '2026-09-30', false, true, null),
  (7122, 12, 16, 'BE', 'Alle Möglichkeiten für Tempo 30 auf Berliner Straßen nutzen', '{1204}', 7065, 2, 3, null, 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern; seit 2024 können Länder und Kommunen Tempo 30 leichter anordnen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=63', null, 'belegt', '2026-09-30', false, true, null),
  (7123, 12, 17, 'BE', 'Investitionsmittel für die Instandsetzung von Straßen und Brücken, Sondervermögen nutzen', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=43', null, 'gemischt', '2026-09-30', false, true, null),
  (7124, 12, 17, 'BE', 'Sicheres, zusammenhängendes Radwegenetz, sichere Kreuzungen mit getrennten Ampelphasen', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=49', null, 'gemischt', '2026-09-30', false, true, null),
  (8539, 12, 18, null, 'Elektronische, streckenabhängige Autobahnmaut, deren Einnahmen Unterhalt und Ausbau der Autobahnen finanzieren sollen', '{1201}', 6932, 2, 2, null, 'Macht die Finanzierung der Autobahnen planbarer und unabhängiger vom Haushalt; öffentlich-private Partnerschaften waren laut Bundesrechnungshof bisher oft teurer als konventionelle Vergabe.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=71', null, 'gemischt', '2026-10-07', false, true, null),
  (8540, 12, 18, null, 'Schuldenbremse reformieren: Nettoinvestitionen unter anderem in Infrastruktur werden ausgenommen, Defizitgrenze steigt', '{1201}', 6931, 2, 2, null, 'Mehr Geld für Bund, Länder und Kommunen kann Sanierungsstau abbauen; ob es bei Straßen und Brücken ankommt und verbaut werden kann, hängt von Personal und Verfahren ab. Braucht eine Grundgesetzänderung, wie sie 2025 für das Sondervermögen beschlossen wurde.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=22', null, 'gemischt', '2026-10-07', false, true, null),
  (8541, 12, 18, null, 'Planungs- und Genehmigungsverfahren für Infrastrukturprojekte vereinfachen und auf höchstens drei Monate begrenzen', '{1201,1203}', null, 2, 1, null, 'Schnellere Verfahren verkürzen den Weg zu Ersatzbauten; laut KfW und Fachleuten bremsen aber vor allem Personal und Geld. Eine Frist von drei Monaten für alle Infrastrukturprojekte ist mit EU-Vorgaben zu Umweltprüfung und Beteiligung kaum vereinbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=53', 'https://www.kfw.de/Über-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8542, 12, 18, null, 'Gewerbesteuer ersetzen und Konzessionsabgabenverordnung reformieren, um Kommunalfinanzen zu stärken', '{1202}', null, 1, 1, null, 'Stabilere Einnahmen erleichtern Kommunen die Planung von Investitionen; aufkommensneutral entsteht aber kein zusätzliches Geld für Straßen. Ein Ersatz der Gewerbesteuer berührt Art. 28 und 106 GG und scheiterte bisher an Bund und Ländern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=15', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8543, 12, 18, null, 'Sichere Radwege und Fahrradstraßen ausbauen', '{1204}', 6936, 2, 2, null, 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=69', null, 'gemischt', '2026-10-07', false, true, null),
  (8544, 12, 18, null, 'Bundesweit Tempo 30 innerorts sowie Tempo 80 auf Landstraßen', '{1204}', null, 3, 3, null, 'Niedrigere Tempolimits senken Zahl und Schwere von Unfällen; Frankreich verzeichnete nach Tempo 80 auf Landstraßen 12 % weniger Getötete. Anders als Tempo 30 allein deckt es auch Landstraßen ab. Der Bund kann die StVO mit Zustimmung des Bundesrats ändern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=69', 'https://www.cerema.fr/en/node/7630', 'belegt', '2026-10-07', false, true, 'blind'),
  (8683, 12, 18, 'BE', 'Sofortprogramm für sichere Kreuzungen: Unfallschwerpunkte beseitigen, getrennte Ampelphasen, Schutzinseln und abgesetzte Aufstellflächen.', '{1204}', 8682, 2, 3, null, 'Setzt dort an, wo sich Unfälle mit Radfahrenden häufen, etwa an Kreuzungen mit abbiegenden Autos; Auswertungen zeigen oft Rückgänge, strengere Studien mit Kontrolle der Regression zur Mitte finden aber deutlich kleinere Effekte.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=33', 'https://trid.trb.org/View/482195', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8684, 12, 18, 'BE', 'Radwege, Fahrradstraßen und Radschnellverbindungen zügig ausbauen, gestoppte Radschnellwege wieder aufnehmen.', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=34', null, 'gemischt', '2026-10-08', false, true, null),
  (8685, 12, 18, 'BE', 'An Schulen gezielt über Rücksichtnahme im Straßenverkehr aufklären.', '{1204}', 7066, 1, 3, null, 'Richtet sich an Gruppen mit hohem Risiko, etwa ältere Menschen auf Pedelecs; wie stark Trainings die Zahl schwerer Unfälle senken, ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=33', null, 'offen', '2026-10-08', false, true, null),
  (8686, 12, 18, 'MV', 'Das Land fördert kommunale Radverkehrsprojekte, die Radverkehr von Straßen und Fußgängern trennen, mit Vorrang für Schul- und Pendelwege.', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=56', null, 'gemischt', '2026-10-08', false, true, null),
  (8687, 12, 18, 'MV', 'Das Land gleicht neue gesetzliche Pflichten der Kommunen dauerhaft finanziell aus.', '{1202}', 7061, 1, 2, null, 'Gibt Kommunen Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden sie selbst, und der Landeshaushalt ist begrenzt.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=24', null, 'gemischt', '2026-10-08', false, true, null),
  (8688, 12, 18, 'ST', 'Verlässliche, planbare und bedarfsgerechte Landesfinanzierung der Kommunen, damit sie Aufgaben wie Infrastruktur erfüllen und investieren können.', '{1202}', 7061, 1, 2, null, 'Gibt Kommunen Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden sie selbst, und der Landeshaushalt ist begrenzt.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=119', null, 'gemischt', '2026-10-08', false, true, null),
  (8689, 12, 18, 'ST', 'Feste Fristen und Genehmigungsfiktion bei Bau- und Infrastrukturprojekten, vereinfachte Prüfverfahren und mehr Entscheidungskompetenz der Kommunen.', '{1203}', 7062, 2, 3, null, 'Das Land kann Bauordnung, Vergaberecht und Verwaltungsabläufe selbst ändern und so Verfahren verkürzen; laut KfW bremst aber vor allem fehlendes Personal.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=118', null, 'gemischt', '2026-10-08', false, true, null),
  (8690, 12, 18, 'ST', 'Zusammenhängendes Radnetz mit priorisiertem Bau von Radwegen entlang von Bundes- und Landesstraßen, Lückenschlüssen und beschleunigten Verfahren.', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=98', null, 'gemischt', '2026-10-08', false, true, null),
  (8691, 12, 18, 'ST', 'Unfallhäufungsstellen an Landesstraßen systematisch beseitigen und gefährliche Kreuzungen umgestalten.', '{1204}', 8682, 2, 3, null, 'Setzt dort an, wo sich Unfälle mit Radfahrenden häufen, etwa an Kreuzungen mit abbiegenden Autos; Auswertungen zeigen oft Rückgänge, strengere Studien mit Kontrolle der Regression zur Mitte finden aber deutlich kleinere Effekte.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=92', 'https://trid.trb.org/View/482195', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8692, 12, 18, 'ST', 'Tempo 30 als Standard innerorts, Ausweitung auf Wohngebiete und Schulwege mit Kontrolle.', '{1204}', null, 2, 2, null, 'Weniger Tempo senkt Zahl und Schwere von Unfällen deutlich (Edinburgh: rund 40 % weniger Verletzte); Zonen kann das Land ausweiten, Tempo 30 als Regel innerorts braucht aber eine Änderung der StVO durch den Bund, sonst nur Modellversuche.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=89', 'https://www.engineersireland.ie/Engineers-Journal/News/revealed-slowing-city-traffic-reduces-road-deaths-by-25-study', 'belegt', '2026-10-08', false, true, 'blind');

